#!/usr/bin/env node
/**
 * Regenerate the bundled icon modules from the pinned OpenAI Apps SDK UI
 * source. The generated files are committed (they are build inputs), but the
 * pinned upstream is the single source of truth — never hand-edit path data.
 *
 * Usage:
 *   node scripts/generate-icon-data.mjs --source <dir>
 *
 * `--source` points directly to the pinned upstream's
 * `src/components/Icon/svg` directory. TypeScript's TSX parser reads literal
 * SVG attributes without evaluating source. Unsupported structures reject the
 * entire glyph, rather than silently publishing only its supported paths.
 *
 * Produces:
 *   src/client/icons/icon-data.ts        内联集合（客户端包里）
 *   src/client/icons/icon-data-full.ts   全量集合（仅懒加载资产引用）
 *   src/client/icons/icon-names-full.ts  名字清单（内联，用于识别拼写错误）
 *   ICON-NAMES.md                        完整名单（给人 / SKILL grep 用）
 *
 * Upstream: https://github.com/openai/apps-sdk-ui @ 0f00143c7a639906f1621fe58e1b6be7b5bea46d (MIT).
 */
import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { parseArgs } from 'node:util'
import ts from 'typescript'

const { values } = parseArgs({
  options: {
    source: { type: 'string' },
    out: { type: 'string', default: 'src/client/icons' },
  },
  strict: true,
})

if (values.source === undefined) {
  console.error('usage: node scripts/generate-icon-data.mjs --source <icon-definitions-dir>')
  process.exit(1)
}

/** 内联集合：状态、箭头，以及构图真正会用到的那批计算/文档字形。 */
const INLINE = [
  'Check', 'CheckCircle', 'Info', 'InfoCircle', 'Warning', 'Error', 'X', 'Plus', 'Minus',
  'ArrowDown', 'ArrowUp', 'ArrowRight', 'ArrowLeft', 'ArrowCurvedRight',
  'Function', 'Functions', 'Operator', 'Atom', 'Nodes', 'Connect', 'Share', 'Branch', 'Grid', 'GridAlt', 'Stack',
  'Cube', 'Storage', 'Chart', 'Trending', 'Pulse', 'Speed', 'Timer', 'Clock', 'TableFilled',
  'Code', 'SquareCode', 'Terminal', 'File', 'FileCode', 'Folder', 'Folders', 'Link', 'Paperclip',
  'Lightbulb', 'Book', 'BookOpen', 'GraduationCap', 'Flask', 'Lab', 'Brain', 'Robot', 'Sparkles',
  'ShieldCheck', 'Lock', 'Globe', 'WebsiteNetwork', 'Search', 'MagnifyingGlassSearch',
  'PluginPuzzle', 'Settings', 'Bolt', 'Compass', 'Trash', 'Report',
]

const HEADER = `/**
 * OpenAI Apps SDK UI icons — https://github.com/openai/apps-sdk-ui
 * Pinned commit 0f00143c7a639906f1621fe58e1b6be7b5bea46d · MIT · Copyright 2025 OpenAI.
 * See THIRD_PARTY_NOTICES.md.
 *
 * Generated by scripts/generate-icon-data.mjs — do not hand-edit.
 */`

// React SVG attribute names are kept as written in the upstream TSX. Root
// paint stays on the SVG, so SVG inheritance and per-shape overrides survive.
const SVG_ATTRS = [
  'fill', 'fillRule', 'clipRule', 'stroke', 'strokeWidth', 'strokeLinecap',
  'strokeLinejoin', 'opacity', 'd', 'x', 'y', 'width', 'height', 'rx', 'ry',
  'cx', 'cy', 'r', 'x1', 'y1', 'x2', 'y2', 'points', 'transform',
]
const RENDER_TAGS = new Set(['path', 'rect', 'circle', 'ellipse', 'line', 'polyline', 'polygon'])

function literal(initializer) {
  if (initializer === undefined) throw new Error('boolean SVG attribute')
  const value = ts.isJsxExpression(initializer) ? initializer.expression : initializer
  if (value !== undefined && ts.isStringLiteral(value)) return value.text
  if (value !== undefined && ts.isNumericLiteral(value)) return Number(value.text)
  if (value !== undefined && ts.isPrefixUnaryExpression(value)
    && value.operator === ts.SyntaxKind.MinusToken && ts.isNumericLiteral(value.operand)) {
    return -Number(value.operand.text)
  }
  throw new Error('non-literal SVG attribute')
}

function attributes(opening, root = false) {
  const attrs = {}
  for (const prop of opening.attributes.properties) {
    // Only the component's root props spread is deliberately replaced by our
    // fixed optical size/accessibility props; never execute it.
    if (ts.isJsxSpreadAttribute(prop)) {
      if (root && ts.isIdentifier(prop.expression) && prop.expression.text === 'props') continue
      throw new Error('unsupported SVG spread')
    }
    const key = prop.name.getText()
    if (root && ['width', 'height', 'className'].includes(key)) continue
    if (!(root && key === 'viewBox') && !SVG_ATTRS.includes(key)) {
      throw new Error(`unsupported attribute ${key}`)
    }
    attrs[key] = literal(prop.initializer)
  }
  return attrs
}

function readGlyph(file, source) {
  const ast = ts.createSourceFile(file, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TSX)
  if (ast.parseDiagnostics.length > 0) throw new Error('invalid TSX')
  const roots = []
  function find(node) {
    if (ts.isJsxElement(node) && node.openingElement.tagName.getText(ast) === 'svg') roots.push(node)
    ts.forEachChild(node, find)
  }
  find(ast)
  if (roots.length !== 1) throw new Error('expected one SVG root')
  const root = roots[0]
  const attrs = attributes(root.openingElement, true)
  if (typeof attrs.viewBox !== 'string') throw new Error('missing viewBox')
  const viewBox = attrs.viewBox
  delete attrs.viewBox
  const shapes = []
  for (const child of root.children) {
    if (ts.isJsxText(child) && child.text.trim() === '') continue
    if (!ts.isJsxSelfClosingElement(child)) throw new Error('unsupported nested SVG structure')
    const tag = child.tagName.getText(ast)
    if (!RENDER_TAGS.has(tag)) throw new Error(`unsupported element ${tag}`)
    shapes.push({ tag, attrs: attributes(child) })
  }
  if (shapes.length === 0) throw new Error('no shapes')
  return { viewBox, attrs, shapes }
}

const catalogue = {}
const skipped = []
for (const file of readdirSync(values.source).sort()) {
  if (!/\.[jt]sx$/.test(file)) continue
  const name = file.replace(/\.[jt]sx$/, '')
  try {
    catalogue[name] = readGlyph(file, readFileSync(join(values.source, file), 'utf8'))
  } catch (error) {
    skipped.push(`${name}: ${error.message}`)
  }
}

const names = Object.keys(catalogue).sort()
const missingInline = INLINE.filter(name => catalogue[name] === undefined)
if (missingInline.length > 0) {
  console.error(`generate-icon-data: 内联名单在上游缺失: ${missingInline.join(', ')}`)
  console.error('  不再静默过滤——请修正 INLINE，或等上游补齐该字形。')
  process.exit(1)
}

const body = (list) => `{\n${list.map(name => {
  const glyph = catalogue[name]
  return `  ${JSON.stringify(name)}: {\n    viewBox: ${JSON.stringify(glyph.viewBox)},\n    attrs: ${JSON.stringify(glyph.attrs)},\n    shapes: [\n${glyph.shapes.map(shape => `      ${JSON.stringify(shape)},`).join('\n')}\n    ],\n  },`
}).join('\n')}\n}`
const TYPE_BLOCK = `import type { SVGProps } from 'react'

export interface BundledIcon {
  viewBox: string
  /** Root attributes preserve SVG paint inheritance. */
  attrs: IconAttributes
  shapes: IconShape[]
}

export type IconAttributes = Pick<SVGProps<SVGSVGElement>,
  ${SVG_ATTRS.map(key => `'${key}'`).join(' | ')}>

export interface IconShape {
  tag: ${[...RENDER_TAGS].map(tag => `'${tag}'`).join(' | ')}
  attrs: IconAttributes
}`

mkdirSync(values.out, { recursive: true })
writeFileSync(join(values.out, 'icon-data-full.ts'),
  `${HEADER}\n/**\n * 全量字形（${names.length} 个）。只有懒加载资产入口引用它，不进入客户端包。\n */\n${TYPE_BLOCK}\n\nexport const ICONS_FULL: Readonly<Record<string, BundledIcon>> = ${body(names)}\n`)

writeFileSync(join(values.out, 'icon-data.ts'),
  `${HEADER}\n/**\n * 内联集合（${INLINE.length} 个）：随客户端包发布，常见构图无需下载即可渲染。\n * 其余字形见 icon-data-full.ts，经 lib/assets/icons.js 按需载入。\n */\n${TYPE_BLOCK}\n\nexport const ICONS: Readonly<Record<string, BundledIcon>> = ${body(INLINE)}\n`)

writeFileSync(join(values.out, 'icon-names-full.ts'),
  `${HEADER}\n/**\n * 全部规范名（${names.length}）。只内联名字，好让渲染器区分「拼错」和「还没下载」：\n * 不在这里的名字立刻走中性圆点兜底，不会触发全量字形包下载。\n */\nexport const ICON_NAMES_FULL: readonly string[] = ${JSON.stringify(names)}\n`)

// ICON-NAMES.md 也由脚本产出，避免手抄漂移（review #6）。
// out mirrors src/client/icons; the documentation lives at that tree's root.
const repoRoot = join(values.out, '..', '..', '..')
writeFileSync(join(repoRoot, 'ICON-NAMES.md'), `# 图标名清单（全量 ${names.length} 个）

> 本文件由 \`scripts/generate-icon-data.mjs\` 生成，请勿手改。
> 来源：OpenAI Apps SDK UI，commit \`0f00143c7a639906f1621fe58e1b6be7b5bea46d\`，MIT。

\`icon\` 节点接受下列任意名字（区分大小写）。未知名字渲染为中性圆点，
不会丢块，也不会触发下载。

不支持的嵌套 SVG 结构按整图排除（${skipped.length} 个）：
${skipped.map(reason => `- ${reason}`).join('\n')}

## 内联（${INLINE.length} 个，无需下载）

\`\`\`text
${INLINE.join(' ')}
\`\`\`

## 按需载入（${names.length - INLINE.length} 个）

首次用到非内联名字时，会一次性拉取 \`lib/assets/icons.js\`（约 1 MB），
此后本页全部可用。

\`\`\`text
${names.filter(n => !INLINE.includes(n)).join(' ')}
\`\`\`
`)

console.log(`icons: ${names.length} total / ${INLINE.length} inline / ${names.length - INLINE.length} lazy`)
console.log(`excluded whole glyphs: ${skipped.length}\n${skipped.join('\n')}`)
